    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '181: The "Pearl Index" is a measure of:', '["Contraceptive effectiveness (pregnancies per 100 woman-years)", "Maternal mortality", "Fetal growth", "Cervical dilation"]', 0, 'Lower Pearl Index = higher effectiveness. (Beckmann)'),
    (v_topic_id, '182: Which of the following is considered a "Long-Acting Reversible Contraceptive" (LARC)?', '["The Pill", "Depo-Provera", "Intrauterine Device (IUD) and Nexplanon implant", "Condoms"]', 2, 'LARCs have the highest effectiveness because they don''t depend on daily user adherence. (ACOG)'),
    (v_topic_id, '183: What is the primary mechanism of action of the Copper IUD (Paragard)?', '["Suppression of ovulation", "Creating a sterile inflammatory response in the uterus that is spermicidal", "Thickening cervical mucus", "Thinning the endometrium"]', 1, 'Copper ions are toxic to sperm. (Williams)'),
    (v_topic_id, '184: How long is the Levonorgestrel IUD (e.g., Mirena) typically FDA-approved for?', '["3 years", "5-8 years (depending on model)", "10 years", "Life"]', 1, 'Mirena/Liletta are approved for up to 8 years in recent guidelines. (ACOG)'),
    (v_topic_id, '185: A primary non-contraceptive benefit of the Levonorgestrel IUD is:', '["Prevention of STIs", "Significant reduction in menstrual blood loss (menorrhagia)", "Weight loss", "Improved acne"]', 1, 'Often used for treatment of Heavy Menstrual Bleeding. (Beckmann)'),
    (v_topic_id, '186: The Copper IUD is often associated with which common side effect?', '["Amenorrhea", "Increased menstrual bleeding and cramping", "Weight gain", "Hirsutism"]', 1, 'Does not contain hormones, so menstruation continues and may be heavier. (Williams)'),
    (v_topic_id, '187: "Nexplanon" is a single-rod contraceptive implant that contains:', '["Estrogen", "Etonogestrel (Progestin)", "Copper", "Testosterone"]', 1, 'Placed subdermally in the upper arm; lasts 3 years. (Beckmann)'),
    (v_topic_id, '188: What is the primary mechanism of the Nexplanon implant?', '["Inducing abortion", "Suppression of ovulation and thickening of cervical mucus", "Blocking the fallopian tubes", "Altering pH"]', 1, 'Highly effective progestin-only method. (ACOG)'),
    (v_topic_id, '189: Combined Oral Contraceptive (COC) pills contain:', '["Estrogen and Progestin", "Progestin only", "Estrogen only", "hCG"]', 0, 'The estrogen provides cycle control and the progestin provides the primary contraceptive effect. (Williams)'),
    (v_topic_id, '190: COCs primarily prevent pregnancy by:', '["Preventing fertilization", "Supplying feedback inhibition of GnRH, FSH, and LH to suppress ovulation", "Causing early miscarriage", "Killing sperm"]', 1, 'Ovulation is inhibited. (Beckmann)'),
    (v_topic_id, '191: Which of the following is a RECOGNIZED non-contraceptive benefit of COCs?', '["Decreased risk of ovarian and endometrial cancer", "Decreased risk of breast cancer", "Prevention of HIV", "Weight gain"]', 0, 'COCs reduce the risk of ovarian and endometrial cancers by ~50%. (ACOG)'),
    (v_topic_id, '192: Which of the following is an ABSOLUTE contraindication to the use of combined (estrogen-containing) hormonal contraceptives?', '["Maternal age 35", "Smoker < 35 years old", "History of DVT or Pulmonary Embolism", "Controlled HTN"]', 2, 'Estrogen increases the risk of thromboembolism. (CDC MEC)'),
    (v_topic_id, '193: A 38-year-old woman who smokes > 15 cigarettes/day should NOT use:', '["Copper IUD", "Nexplanon", "Combined Oral Contraceptive Pills", "Progestin-only pills"]', 2, 'Smoking + Estrogen + Age >= 35 = High stroke/VTE risk. (ACOG)'),
    (v_topic_id, '194: "Progestin-only pills" (the "Mini-pill") are particularly useful for:', '["Women who are breastfeeding", "Women with contraindications to estrogen", "Women who want to stop periods", "Both A and B"]', 3, 'Does not interfere with milk production and avoids estrogen risks. (Williams)'),
    (v_topic_id, '195: A major disadvantage of the "Mini-pill" (Norethindrone) is:', '["It must be taken at the same time every day (3-hour window)", "It causes weight gain", "It increases cancer risk", "It causes acne"]', 0, 'Very sensitive to timing; if > 3 hours late, a backup method is needed. (Beckmann)'),
    (v_topic_id, '196: "Depo-Provera" (DMPA) is an injectable contraceptive given every:', '["Month", "3 months (12 weeks)", "6 months", "Year"]', 1, 'Medroxyprogesterone acetate. (ACOG)'),
    (v_topic_id, '197: A common side effect of DMPA that often leads to discontinuation is:', '["Hirsutism", "Irregular spotting or weight gain", "DVT", "Cancer"]', 1, 'Irregular bleeding is very common initially; amenorrhea often follows. (Williams)'),
    (v_topic_id, '198: Long-term use of DMPA (> 2 years) is associated with a reversible decrease in:', '["Visual acuity", "Bone mineral density", "Fertility", "Memory"]', 1, 'Black box warning, though clinical significance is debated; counseling on Calcium/Vit D is key. (ACOG)'),
    (v_topic_id, '199: The "NuvaRing" is a combined hormonal method that is worn in the vagina for:', '["1 day", "1 week", "3 weeks (then removed for 1 week)", "1 month"]', 2, 'Releases estrogen and progestin. (Beckmann)'),
    (v_topic_id, '200: "Emergency Contraception" (e.g., Plan B) works by:', '["Causing an abortion", "Delaying or inhibiting ovulation", "Blocking implantation", "Killing the embryo"]', 1, 'It does not work if ovulation has already occurred and a pregnancy is established. (ACOG)'),
    (v_topic_id, '201: What is the most effective method of "Emergency Contraception" if used within 5 days of unprotected sex?', '["Plan B (Levonorgestrel)", "Ella (Ulipristal acetate)", "Copper IUD", "High-dose COCs"]', 2, 'The Copper IUD is the most effective EC method. (ACOG)'),
    (v_topic_id, '202: "Barrier methods" (Condoms, Diaphragms) have higher failure rates than hormonal methods primarily because:', '["They are less effective biologically", "They require perfect use every time and are subject to user error", "They break easily", "They cause infections"]', 1, 'Typical use failure rates are ~13-18% for condoms. (Beckmann)'),
    (v_topic_id, '203: Diaphragms must be used in conjunction with _____ to be effective.', '["The pill", "Spermicide", "Antibiotics", "A belt"]', 1, 'Diaphragm + Spermicide. (Williams)'),
    (v_topic_id, '204: A woman using a diaphragm should leave it in place for at least _____ hours after intercourse.', '["1", "6", "12", "24"]', 1, 'But not more than 24 hours (due to TSS risk). (ACOG)'),
    (v_topic_id, '205: "Natural Family Planning" (NFP) or Fertility Awareness methods rely on:', '["Withdrawal", "Predicting the fertile window and abstaining from sex", "Using a thermometer", "Both B and C"]', 3, 'Includes tracking temperature, cervical mucus, and cycle length. (Beckmann)'),
    (v_topic_id, '206: The "Standard Days Method" is only appropriate for women with cycles lasting:', '["21-35 days", "26-32 days", "Regular intervals of 28 days only", "Any length"]', 1, 'Requires regular cycles to be effective. (ACOG)'),
    (v_topic_id, '207: "Male Sterilization" (Vasectomy) is highly effective, but it is not immediate because:', '["The procedure takes time to heal", "Stored sperm in the vas deferens must be cleared (usually takes 2-3 months or 20 ejaculations)", "The testicles still produce sperm", "It is not permanent"]', 1, 'A follow-up semen analysis is mandatory to confirm azoospermia. (Beckmann)'),
    (v_topic_id, '208: "Female Sterilization" (Tubal Ligation) primarily works by:', '["Removing the ovaries", "Blocking or cutting the fallopian tubes to prevent sperm/egg meeting", "Hysterectomy", "Burning the lining"]', 1, 'Permanent and highly effective. (Williams)'),
    (v_topic_id, '209: Salpingectomy (total removal of the fallopian tubes) is increasingly preferred over tubal ligation because it reduces the risk of:', '["Ovarian cancer", "Ectopic pregnancy", "Endometrial cancer", "Both A and B"]', 3, 'Many high-grade serous ovarian cancers originate in the fimbriated end of the tube. (ACOG)'),
    (v_topic_id, '210: What is the major "long-term" risk after a tubal ligation?', '["Heavier periods", "Ectopic pregnancy (if pregnancy does occur)", "Menopause", "Weight gain"]', 1, 'If the procedure fails, the resulting pregnancy is highly likely to be ectopic. (Beckmann)'),
    (v_topic_id, '211: "Sterilization regret" is highest in women who:', '["Are older than 40", "Are younger than 30 at the time of the procedure", "Have 4 children", "Are married"]', 1, 'Age < 30 is a major risk factor for regret. (CREST study)'),
    (v_topic_id, '212: Which contraceptive method is most appropriate for a woman with a history of "Estrogen-sensitive breast cancer"?', '["COCs", "Copper IUD", "NuvaRing", "The Patch"]', 1, 'Non-hormonal methods are preferred for breast cancer survivors. (CDC MEC)'),
    (v_topic_id, '213: A patient on "Anticonvulsants" (like Phenytoin or Carbamazepine) may have decreased effectiveness of:', '["Condoms", "The Copper IUD", "Combined Oral Contraceptive Pills", "Diaphragms"]', 2, 'Enzyme-inducing drugs increase hepatic metabolism of hormonal steroids. (ACOG)'),
    (v_topic_id, '214: The "patch" (Xulane) is less effective in women weighing more than:', '["150 lbs", "198 lbs (90 kg)", "250 lbs", "None"]', 1, 'Higher failure rates in obese women. (FDA/ACOG)'),
    (v_topic_id, '215: If a woman misses ONE COC pill, what is the standard advice?', '["Stop the pack and wait for period", "Take the missed pill as soon as remembered and the next at the regular time", "Use backup for a month", "Start a new pack"]', 1, 'No backup is usually needed if only one pill is missed. (ACOG)'),
    (v_topic_id, '216: If a woman misses TWO OR MORE COC pills in a row, she should:', '["Take the most recent missed pill, discard the others, and use backup for 7 days", "Double up for 3 days", "Take the whole week''s pills at once", "Quit the pill"]', 0, 'Backup contraception is needed. (Beckmann)'),
    (v_topic_id, '217: "Bilateral Salpingo-Oophorectomy" (BSO) is:', '["Removal of the uterus", "Removal of both tubes and both ovaries", "Sterilization only", "Removal of the cervix"]', 1, 'Results in surgical menopause. (Williams)'),
    (v_topic_id, '218: A woman who gets an IUD inserted should be taught to:', '["Check for the strings after each period", "Feel for the IUD in the cervix", "Take antibiotics", "Avoid exercise"]', 0, 'Standard patient education. (Beckmann)'),
    (v_topic_id, '219: IUD insertion in a woman with an active STI (Gonorrhea/Chlamydia) significantly increases the risk of:', '["Cancer", "Pelvic Inflammatory Disease (PID)", "Diabetes", "Twins"]', 1, 'STIs should be treated; IUD can be placed once infection is cleared. (ACOG)'),
    (v_topic_id, '220: Does the IUD cause abortion?', '["Yes, always", "No, it primarily prevents fertilization", "Only the copper one", "Only the hormonal one"]', 1, 'It is a contraceptive, not an abortifacient. (Williams)'),
    (v_topic_id, '221: Which method has the lowest "Typical Use" failure rate?', '["Male Condom", "The Pill", "Vasectomy", "Diaphragm"]', 2, 'Permanent methods and LARCs have the lowest failure rates. (CDC)'),
    (v_topic_id, '222: Combined hormonal contraceptives increase the risk of which type of stroke?', '["Ischemic stroke", "Hemorrhagic stroke", "Both", "Neither"]', 0, 'Risk is low in young, healthy non-smokers. (Beckmann)'),
    (v_topic_id, '223: Which medication is often used to treat "Excessive hair growth" (Hirsutism) in PCOS patients and is also a contraceptive benefit of COCs?', '["Metformin", "Spironolactone", "Ethinyl Estradiol", "Progesterone"]', 2, 'COCs increase Sex Hormone Binding Globulin (SHBG), lowering free testosterone. (Williams)'),
    (v_topic_id, '224: "Ulipristal acetate" (Ella) is an emergency contraceptive that is a:', '["Progestin", "Selective Progesterone Receptor Modulator (SPRM)", "Estrogen", "Prostaglandin"]', 1, 'Effective for up to 120 hours. (ACOG)'),
    (v_topic_id, '225: The "Withdrawal" method (Coitus interruptus) has a typical use failure rate of approximately:', '["2%", "22%", "50%", "90%"]', 1, 'Highly subject to user error. (Beckmann)'),
    (v_topic_id, '226: Spermicides containing "Nonoxynol-9" may increase the risk of _____ transmission due to vaginal irritation.', '["Syphilis", "HIV", "Chlamydia", "HPV"]', 1, 'Frequent use can disrupt the vaginal epithelium. (CDC)'),
    (v_topic_id, '227: After "Unprotected Intercourse," the risk of pregnancy is highest if it occurs:', '["During the period", "2 days BEFORE ovulation", "3 days AFTER ovulation", "During the luteal phase"]', 1, 'Sperm can live for 5 days; the fertile window is the 5 days before and the day of ovulation. (Williams)'),
    (v_topic_id, '228: "Essure" was a form of permanent sterilization that involved:', '["Surgery", "Hysteroscopic placement of micro-inserts into the fallopian tubes", "A ring", "A patch"]', 1, 'No longer on the market in most regions due to side effects. (ACOG)'),
    (v_topic_id, '229: Does "Tubal Ligation" protect against STIs?', '["Yes", "No", "Only if done laparoscopically", "Only if done after age 35"]', 1, 'Only barrier methods (condoms) provide significant STI protection. (Beckmann)'),
    (v_topic_id, '230: "Emergency Contraception" should be offered to a woman after sexual assault if:', '["She is in her fertile window", "Regardless of the cycle phase", "Only if she is not on the pill", "Only if she asks"]', 1, 'Standard of care for assault victims. (ACOG)'),
    (v_topic_id, '231: Which of the following is a "Barrier" method for the female?', '["Nexplanon", "Female Condom", "NuvaRing", "IUD"]', 1, 'A polyurethane or nitrile sheath. (Williams)'),
    (v_topic_id, '232: "Spontaneous Abortion" is the loss of pregnancy before _____ weeks.', '["12", "20", "24", "28"]', 1, 'Pregnancy loss after 20 weeks is a Stillbirth/Intrauterine Fetal Demise. (Beckmann)'),
    (v_topic_id, '233: "Medical Abortion" typically uses a combination of which two drugs?', '["Estrogen and Progesterone", "Mifepristone and Misoprostol", "Methotrexate and Misoprostol", "Aspirin and Oxytocin"]', 1, 'Mifepristone blocks progesterone; Misoprostol causes contractions. (ACOG)'),
    (v_topic_id, '234: Mifepristone is a:', '["Prostaglandin", "Progesterone receptor antagonist", "Estrogen", "Folic acid antagonist"]', 1, 'Used to "prime" the uterus and detach the embryo. (Beckmann)'),
    (v_topic_id, '235: Surgical abortion in the first trimester is most commonly performed via:', '["Dilation and Evacuation (D&E)", "Suction Curettage (D&C)", "Hysterectomy", "C-section"]', 1, 'D&C is for 1st trimester; D&E is for 2nd trimester. (Williams)'),
    (v_topic_id, '236: The most common complication of a first-trimester surgical abortion is:', '["Infection", "Retained products of conception (RPOC)", "Uterine perforation", "Hemorrhage"]', 1, 'Incomplete evacuation may require a repeat procedure. (Beckmann)'),
    (v_topic_id, '237: A "Missed Abortion" is defined as:', '["Vaginal bleeding with an open os", "Fetal death without any symptoms of bleeding or cramping and a closed os", "Cramping with a closed os", "Loss of only one twin"]', 1, 'Often found incidentally on ultrasound. (Williams)'),
    (v_topic_id, '238: An "Inevitable Abortion" is characterized by:', '["Closed os", "Vaginal bleeding and an OPEN cervix", "A healthy heartbeat", "Passing of all tissue"]', 1, 'The process is underway and cannot be stopped. (Beckmann)'),
    (v_topic_id, '239: Rh-negative women undergoing ANY abortion (spontaneous, medical, or surgical) should receive:', '["Antibiotics", "RhoGAM", "Iron", "Oxygen"]', 1, 'To prevent sensitization for future pregnancies. (ACOG)'),
    (v_topic_id, '240: What is the most common chromosomal abnormality found in first-trimester spontaneous abortions?', '["Trisomy 21", "Autosomal Trisomies (overall)", "Monosomy X (Turner)", "Triploidy"]', 1, 'Autosomal trisomies (13, 16, 18, 21, 22) are the most common group. (Williams)');
